import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api"; 

const ROLES = [
  {id:"student", label:"Student",  emoji:"🎓", placeholder:"your-email@example.com"},
  {id:"company", label:"Company",  emoji:"🏢", placeholder:"hr@company.com"},
  {id:"admin",   label:"Admin",    emoji:"🏛️", placeholder:"admin@stag.io"},
];

export default function Login() {
  const [role, setRole]         = useState("student");
  const [email, setEmail]       = useState(""); // هذا سيستخدم كـ username في Django
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading]   = useState(false);
  
  const navigate = useNavigate();
  const cfg = ROLES.find(r => r.id === role);

  const handleLogin = async () => {
    if (!email || !password) {
      alert("الرجاء ملء الحقول المطلوبة");
      return;
    }

    setLoading(true);
    try {
      // 1. إرسال طلب تسجيل الدخول
      // ملاحظة: Django JWT يتوقع 'username' افتراضياً، إذا كنت تستخدم الإيميل للدخول
      // تأكد أن الـ Backend مهيأ لذلك، وإلا أرسل الإيميل في حقل 'username'
      const response = await api.post('login/', {
        username: email, // أو email حسب إعدادات Django الخاصة بك
        password: password
      });

      // 2. حفظ التوكين في المتصفح
      localStorage.setItem('access_token', response.data.access);
      localStorage.setItem('refresh_token', response.data.refresh);

      // 3. جلب بيانات المستخدم لمعرفة الـ Role (بما أن JWT الافتراضي لا يعيده)
      const userRes = await api.get('profile/'); // الرابط الذي أنشأناه في views.py
      const userRole = userRes.data.role.toLowerCase();
      
      localStorage.setItem('userRole', userRole);

      // 4. التوجيه بناءً على الدور الحقيقي من قاعدة البيانات
      if (userRole === "student") navigate("/student/dashboard");
      else if (userRole === "company") navigate("/company/dashboard");
      else if (userRole === "admin") navigate("/admin/dashboard");
      else alert("عذراً، نوع الحساب غير معروف");

    } catch (error) {
      console.error("Login error:", error);
      const errorMsg = error.response?.data?.detail || "فشل تسجيل الدخول. تأكد من البريد وكلمة المرور.";
      alert(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-[#fdf9f5]">
      {/* القسم الأيسر - جمالي */}
      <div className="hidden lg:flex lg:w-[52%] bg-slate-900 flex-col relative overflow-hidden">
        <div className="absolute inset-0 dot-grid opacity-40"/>
        <div className="relative p-10">
          <Link to="/" className="font-syne font-extrabold text-2xl text-white tracking-tight">Stag<span className="text-[#3b82f6]">.</span>io</Link>
        </div>
        <div className="flex-1 flex flex-col justify-center px-12 pb-16 relative">
          <h1 className="font-syne font-extrabold text-white leading-tight mb-5 text-4xl lg:text-5xl">
            رحلة تربصك تبدأ <span className="text-blue-400">من هنا.</span>
          </h1>
        </div>
      </div>

      {/* القسم الأيمن - فورم الدخول */}
      <div className="flex-1 flex flex-col justify-center items-center px-6 py-12">
        <div className="w-full max-w-md">
          <h2 className="font-syne font-extrabold text-slate-900 text-3xl mb-8">تسجيل الدخول</h2>

          {/* اختيار الدور */}
          <div className="bg-slate-100 rounded-xl p-1 flex mb-7">
            {ROLES.map(r => (
              <button key={r.id} onClick={() => setRole(r.id)}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all ${role===r.id?"bg-white text-slate-900 shadow-sm":"text-slate-500"}`}>
                <span>{r.emoji}</span><span>{r.label}</span>
              </button>
            ))}
          </div>
          <div className="space-y-5">
            <input 
              type="email" 
              value={email} 
              onChange={e=>setEmail(e.target.value)} 
              placeholder={cfg.placeholder} 
              className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" 
            />
            <div className="relative">
              <input type={showPass?"text":"password"} 
                value={password} 
                onChange={e=>setPassword(e.target.value)} 
                placeholder="••••••••" 
                className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              />
              <button type="button" onClick={()=>setShowPass(!showPass)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">
                {showPass?"🙈":"👁️"}
              </button>
            </div>

            <button 
              onClick={handleLogin} 
              disabled={loading}
              className={`w-full bg-slate-900 text-white font-semibold py-3 rounded-xl text-sm flex justify-center items-center gap-2 ${loading ? 'opacity-70 cursor-not-allowed' : ''}`}
            >
              {loading ? "جاري الدخول..." : "دخول إلى Stag.io ←"}
            </button>
            
            <p className="text-center text-sm text-slate-600 mt-4">
              ليس لديك حساب؟ <Link to="/register" className="text-blue-600 font-bold">سجل الآن</Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
